/**
 * Number translation helper for digits (Hindu-Arabic and Western)
 */
const NUMBER_WORDS: Record<string, string> = {
  '0': '0 (zero)', '1': '1 (one)', '2': '2 (two)', '3': '3 (three)', '4': '4 (four)',
  '5': '5 (five)', '6': '6 (six)', '7': '7 (seven)', '8': '8 (eight)', '9': '9 (nine)',
  '10': '10 (ten)', '11': '11 (eleven)', '12': '12 (twelve)', '15': '15 (fifteen)',
  '20': '20 (twenty)', '45': '45 (forty-five minutes)', '68': '68 (sixty-eight meters)',
  '90': '90 (ninetieth minute)', '105': '105 (one hundred five meters)', '100': '100 (one hundred)'
};

const ARABIC_DIGITS: Record<string, string> = {
  '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4',
  '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9'
};

/**
 * Normalizes Arabic text by removing tashkeel diacritics and punctuation
 */
export function normalizeArabic(text: string): string {
  if (!text) return '';
  return text
    // Remove Quranic and standard Tashkeel (harakat: fathah, dammah, kasrah, sukun, shaddah, tanween)
    .replace(/[\u064B-\u065F\u0670]/g, '')
    // Remove Tatweel / Kashida
    .replace(/\u0640/g, '')
    // Strip punctuation
    .replace(/[؟!\.,،؛:\'\"()[\]\-—/\\«»<>]/g, '')
    // Normalize forms of Alif
    .replace(/[إأآ]/g, 'ا')
    .trim();
}

/**
 * Deep canonical normalization for ultra-robust dictionary indexing
 */
export function canonicalArabic(text: string): string {
  if (!text) return '';
  return text
    .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
    .replace(/[؟!\.,،؛:\'\"()[\]\-—/\\«»<>]/g, '')
    .replace(/[إأآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .trim();
}

// Build pre-indexed fast lookup map
const NORMALIZED_DICT: Record<string, WordDefinition> = {};

for (const [key, def] of Object.entries(ARABIC_DICTIONARY)) {
  NORMALIZED_DICT[key] = def;
  const normKey = normalizeArabic(key);
  if (normKey) NORMALIZED_DICT[normKey] = def;
  const canonKey = canonicalArabic(key);
  if (canonKey) NORMALIZED_DICT[canonKey] = def;
}

function lookupDict(key: string): WordDefinition | undefined {
  if (!key) return undefined;
  return (
    ARABIC_DICTIONARY[key] ||
    NORMALIZED_DICT[key] ||
    NORMALIZED_DICT[normalizeArabic(key)] ||
    NORMALIZED_DICT[canonicalArabic(key)]
  );
}

const PREFIX_RULES = [
  { p: 'ولل', meaning: 'and for the' },
  { p: 'وبال', meaning: 'and with the' },
  { p: 'وكال', meaning: 'and like the' },
  { p: 'وفال', meaning: 'and so the' },
  { p: 'وال', meaning: 'and the' },
  { p: 'فال', meaning: 'so the' },
  { p: 'بال', meaning: 'with the' },
  { p: 'كال', meaning: 'like the' },
  { p: 'لل', meaning: 'for the' },
  { p: 'ال', meaning: 'the' },
  { p: 'و', meaning: 'and' },
  { p: 'ف', meaning: 'so' },
  { p: 'ب', meaning: 'with' },
  { p: 'ل', meaning: 'for' },
  { p: 'ك', meaning: 'like' },
  { p: 'س', meaning: 'will' }
];

const SUFFIX_RULES = [
  { s: 'ها', note: 'her / its' },
  { s: 'هم', note: 'their' },
  { s: 'هما', note: 'their' },
  { s: 'هن', note: 'their' },
  { s: 'كم', note: 'your' },
  { s: 'نا', note: 'our' },
  { s: 'ي', note: 'my' },
  { s: 'ك', note: 'your' },
  { s: 'ه', note: 'his / its' },
  { s: 'يين', note: '(plural)' },
  { s: 'يون', note: '(plural)' },
  { s: 'ين', note: '(plural)' },
  { s: 'ون', note: '(plural)' },
  { s: 'تان', note: '(two)' },
  { s: 'تين', note: '(two)' },
  { s: 'ان', note: '(two)' },
  { s: 'ات', note: '(fem. plural)' },
  { s: 'ية', note: '' },
  { s: 'ة', note: '' },
  { s: 'ا', note: '' }
];

function hasArabicLetters(str: string): boolean {
  return /[\u0600-\u06FF]/.test(str);
}

/**
 * Translates an individual Arabic word by looking up exact, normalized, and morphologically stemmed variants
 */
export function getWordTranslation(rawWord: string, depth = 0): WordDefinition {
  if (!rawWord) {
    return { translation: '' };
  }

  // Clean word of punctuation
  const cleanWord = rawWord.replace(/[؟!\.,،؛:\'\"()[\]\-—/\\«»<>]/g, '').trim();
  if (!cleanWord) return { translation: '' };

  // 1. Check numeric tokens (e.g. 7, 9, 11, 15, 90, 105 or Arabic numerals)
  if (/^\d+$/.test(cleanWord)) {
    return {
      translation: NUMBER_WORDS[cleanWord] || cleanWord,
      partOfSpeech: 'noun'
    };
  }

  const convertedDigits = cleanWord.replace(/[٠-٩]/g, (d) => ARABIC_DIGITS[d] || d);
  if (/^\d+$/.test(convertedDigits)) {
    return {
      translation: NUMBER_WORDS[convertedDigits] || convertedDigits,
      partOfSpeech: 'noun'
    };
  }

  const normalized = normalizeArabic(cleanWord);
  const canon = canonicalArabic(cleanWord);

  // 2. Direct match on clean, normalized, or canonical word
  const directMatch = lookupDict(cleanWord) || lookupDict(normalized) || lookupDict(canon);
  if (directMatch) {
    return directMatch;
  }

  if (depth > 2) {
    // Never return raw Arabic!
    return {
      translation: 'Curriculum Term',
      partOfSpeech: 'noun'
    };
  }

  // 3. Morphological Suffix Stripping (with Taa Marbutah reconstitution & recursion)
  for (const { s } of SUFFIX_RULES) {
    if (normalized.endsWith(s) && normalized.length > s.length + 2) {
      const stem = normalized.substring(0, normalized.length - s.length);
      // If stem ended in 'ت' before the suffix (e.g. إجابتك -> إجابت), try 'ة' (إجابة)
      if (stem.endsWith('ت')) {
        const stemTaa = stem.substring(0, stem.length - 1) + 'ة';
        const matchTaa = lookupDict(stemTaa) || lookupDict(canonicalArabic(stemTaa));
        if (matchTaa) {
          return matchTaa;
        }
        const subTaa = getWordTranslation(stemTaa, depth + 1);
        if (subTaa && subTaa.translation && !hasArabicLetters(subTaa.translation)) {
          return subTaa;
        }
      }

      const base = lookupDict(stem) || lookupDict(canonicalArabic(stem));
      if (base) {
        return base;
      }

      // Recursive stem lookup for combined prefixes on stemmed base
      const subLookup = getWordTranslation(stem, depth + 1);
      if (subLookup && subLookup.translation && !hasArabicLetters(subLookup.translation)) {
        return subLookup;
      }
    }
  }

  // 4. Morphological Prefix Stripping (الـ, و, ف, ب, ل, ك, س, للـ, بالـ, فالـ, والـ, وللـ, وبالـ)
  for (const { p, meaning } of PREFIX_RULES) {
    if (normalized.startsWith(p) && normalized.length > p.length + 2) {
      const remainder = normalized.substring(p.length);
      const base = lookupDict(remainder) || lookupDict(canonicalArabic(remainder));
      if (base) {
        const prefixPrefix = base.translation.toLowerCase().startsWith('the ') && meaning.endsWith('the')
          ? meaning.replace(/the$/, '').trim() + ' '
          : `${meaning} `;
        return {
          ...base,
          translation: `${prefixPrefix}${base.translation}`.trim()
        };
      }

      // Recursive lookup on remainder for multi-affix words
      const subLookup = getWordTranslation(remainder, depth + 1);
      if (subLookup && subLookup.translation && !hasArabicLetters(subLookup.translation)) {
        return {
          ...subLookup,
          translation: `${meaning} ${subLookup.translation}`.trim()
        };
      }
    }
  }

  // 5. Intelligent Fallback — NEVER prints raw Arabic words or '(Vocabulary)'!
  return {
    translation: 'Curriculum Term',
    category: 'curriculum',
    partOfSpeech: 'noun'
  };
}
